statement:
Write `jsonParse(str)`, which reads the JSON text `str` and returns the JavaScript value it describes. Do it without the built-in `JSON.parse`: here it throws an error while your function runs.

`str` is always valid JSON for exactly one value, and a value is one of:

- `null`, `true` or `false`;
- a number: an optional `-`, digits, and optionally a `.` followed by more digits (never an exponent);
- a string: a `"`, any characters except `"`, and a closing `"`. There are no backslashes, so no escape sequences;
- an array: `[`, values separated by `,`, then `]`;
- an object: `{`, `key:value` pairs separated by `,`, then `}`, where every key is a string. Keys within one object are distinct, and no key is `"__proto__"`.

`str` contains no whitespace at all, not even inside strings. Return arrays with their elements in order, and objects with exactly the keys of the text. Numbers are compared with a tolerance of `1e-5`.

validator:
function validate(input) {
  const [str] = input;
  if (typeof str !== 'string' || str.length < 1 || str.length > 100000) return 'str must be a string of 1 to 10^5 characters.';
  if (/\s/.test(str)) return 'Leave out all whitespace, also inside strings.';
  if (str.includes('\\')) return 'Leave out backslashes: strings here have no escape sequences.';
  try {
    JSON.parse(str);
  } catch {
    return 'str must be valid JSON.';
  }
  // Strings come first in the pattern, so brackets and commas inside them stay part of the string.
  const tokens = str.match(/"[^"]*"|[^",:{}[\]]+|[,:{}[\]]/g);
  const open = [];
  for (let k = 0; k < tokens.length; k++) {
    const token = tokens[k];
    if (token === '{' || token === '[') {
      open.push(token === '{' ? new Set() : null);
      if (open.length > 100) return 'Nest arrays and objects at most 100 levels deep.';
    } else if (token === '}' || token === ']') {
      open.pop();
    } else if (token[0] === '"' && tokens[k + 1] === ':') {
      const keys = open[open.length - 1];
      if (token === '"__proto__"') return 'No key may be "__proto__".';
      if (keys.has(token)) return `The key ${token} appears twice in one object.`;
      keys.add(token);
    } else if (/^-?\d/.test(token)) {
      if (/[eE]/.test(token)) return 'Write numbers without an exponent.';
      if (Math.abs(Number(token)) > 2 ** 53) return 'Keep numbers within 2^53 in size.';
    }
  }
  return null;
}

