function adapt(input, solve, kit) {
  const [str] = input;
  // The problem asks for a parser of your own, so the built-in one is switched off during the call.
  const builtIn = JSON.parse;
  JSON.parse = function () { throw new Error('Solve it without the built-in JSON.parse.'); };
  let result;
  try {
    result = solve(str);
  } finally {
    JSON.parse = builtIn;
  }
  if (result === undefined) throw new Error('jsonParse returned undefined; it should return the value that str describes.');
  const kind = result === null ? 'null' : Array.isArray(result) ? `an array of ${result.length}` : typeof result === 'object' ? `an object with ${Object.keys(result).length} keys` : JSON.stringify(result);
  kit.trace(`jsonParse returns ${kind}`);
  return result;
}

