function jsonParse(str) {
  let i = 0;
  const literals = [['true', true], ['false', false], ['null', null]];

  const parseValue = () => {
    if (str[i] === '{') return parseObject();
    if (str[i] === '[') return parseArray();
    if (str[i] === '"') return parseString();
    for (const [word, value] of literals) {
      if (str.startsWith(word, i)) {
        i += word.length;
        return value;
      }
    }
    return parseNumber();
  };

  const parseString = () => {
    const end = str.indexOf('"', i + 1);
    const text = str.slice(i + 1, end);
    i = end + 1;
    return text;
  };

  const parseNumber = () => {
    const start = i;
    while (i < str.length && '-.0123456789'.includes(str[i])) {
      i++;
    }
    return Number(str.slice(start, i));
  };

  const parseArray = () => {
    const result = [];
    i++;
    while (str[i] !== ']') {
      result.push(parseValue());
      if (str[i] === ',') i++;
    }
    i++;
    return result;
  };

  const parseObject = () => {
    const result = {};
    i++;
    while (str[i] !== '}') {
      const key = parseString();
      i++;
      result[key] = parseValue();
      if (str[i] === ',') i++;
    }
    i++;
    return result;
  };

  return parseValue();
}

