function jsonParse(str) {
  // Cut the text into tokens first, then build the value with an explicit stack instead of recursion.
  const tokens = str.match(/"[^"]*"|-?\d+(?:\.\d+)?|true|false|null|[{}[\],:]/g);
  const stack = [];
  let root;
  const attach = (value) => {
    if (stack.length === 0) {
      root = value;
      return;
    }
    const top = stack[stack.length - 1];
    if (Array.isArray(top.container)) top.container.push(value);
    else top.container[top.key] = value;
  };
  for (let k = 0; k < tokens.length; k++) {
    const token = tokens[k];
    if (token === '{' || token === '[') {
      const container = token === '{' ? {} : [];
      attach(container);
      stack.push({ container, key: null });
    } else if (token === '}' || token === ']') {
      stack.pop();
    } else if (token !== ',' && token !== ':') {
      let value;
      if (token[0] === '"') value = token.slice(1, -1);
      else if (token === 'true') value = true;
      else if (token === 'false') value = false;
      else if (token === 'null') value = null;
      else value = parseFloat(token);
      const top = stack[stack.length - 1];
      if (top && !Array.isArray(top.container) && tokens[k + 1] === ':') top.key = value;
      else attach(value);
    }
  }
  return root;
}

