function generate(rand, size) {
  const small = size === 'small';
  const chars = 'abcxyzAZ0129-.:,{}[]tfnul';
  const word = (most) => Array.from({ length: Math.floor(rand() * (most + 1)) }, () => chars[Math.floor(rand() * chars.length)]).join('');
  const number = () => {
    const roll = rand(), whole = Math.floor(rand() * 2001) - 1000;
    return roll < 0.6 ? whole : roll < 0.9 ? whole / 100 : whole * 1000003;
  };
  const value = (depth) => {
    const roll = rand();
    if (depth >= (small ? 3 : 6) || roll < 0.45) {
      const kind = rand();
      if (kind < 0.35) return number();
      if (kind < 0.7) return word(small ? 4 : 8);
      if (kind < 0.8) return true;
      if (kind < 0.9) return false;
      return null;
    }
    const count = Math.floor(rand() * (small ? 4 : 6));
    if (roll < 0.72) return Array.from({ length: count }, () => value(depth + 1));
    // Assigning keys to an object keeps them distinct.
    const object = {};
    for (let k = 0; k < count; k++) object[word(small ? 3 : 6)] = value(depth + 1);
    return object;
  };
  if (small) return [JSON.stringify(value(0))];
  const top = rand() < 0.5 ? [] : {};
  let textLength = 2;
  for (let k = 0; textLength < 8000; k++) {
    const item = value(1);
    if (Array.isArray(top)) top.push(item);
    else top['key' + k] = item;
    textLength = JSON.stringify(top).length;
    // Drop an item that would push the text past 10,000 characters, and stop.
    if (textLength > 10000) {
      if (Array.isArray(top)) top.pop();
      else delete top['key' + k];
      break;
    }
  }
  return [JSON.stringify(top)];
}
